/// <reference lib="webworker" />
import { analyzeActivities } from '../domain/analysis'
import { parseActivityCsv } from '../domain/csv'
import { normalizePolymarketImport } from '../domain/polymarketAccounting'
import type { PolymarketImport } from '../domain/polymarket'
import type { Activity, AnalysisFilterState, SettlementFallback } from '../domain/types'

type WorkerRequest =
  | { type: 'normalizePolymarket', data: PolymarketImport }
  | { type: 'parse', text: string, fileName: string }
  | { type: 'analyze', activities: Activity[], filters: AnalysisFilterState, friendlyNames: Record<string, string>, fallbacks: Record<string, SettlementFallback> }

self.onmessage = async (event: MessageEvent<WorkerRequest>) => {
  try {
    if (event.data.type === 'normalizePolymarket') {
      const normalized = normalizePolymarketImport(event.data.data)
      self.postMessage({ ok: true, serialized: JSON.stringify({ normalized }) })
      return
    }
    if (event.data.type === 'parse') {
      const snapshot = await parseActivityCsv(event.data.text, event.data.fileName)
      self.postMessage({ ok: true, serialized: JSON.stringify({ snapshot }) })
      return
    }
    const analysis = analyzeActivities(event.data.activities, event.data.filters, event.data.friendlyNames, event.data.fallbacks)
    self.postMessage({ ok: true, serialized: JSON.stringify({ analysis }) })
  } catch (error) {
    self.postMessage({ ok: false, error: error instanceof Error ? error.message : 'Falha ao analisar o CSV' })
  }
}
