import type { EventMetadata } from './types'

const COMPETITIONS: Record<string, string> = {
  KXDOTA2: 'Dota 2',
  KXVALORANT: 'Valorant',
  KXCS2: 'CS2',
  KXLOL: 'League of Legends',
  KXCHESS: 'Chess',
  KXWCGAME: 'Wild Rift'
}

const SERIES_EVENT_TYPES = ['TOTALMAPS', 'MATCH', 'GAME', 'MAP'] as const

export const getSeriesTicker = (ticker: string) => ticker.split('-')[0] ?? ticker

export const getSeriesEventType = (ticker: string) => {
  const seriesTicker = getSeriesTicker(ticker).toLocaleUpperCase()
  return SERIES_EVENT_TYPES.find(type => seriesTicker.endsWith(type)) ?? 'GERAL'
}

export const getSeriesFamily = (ticker: string) => {
  const seriesTicker = getSeriesTicker(ticker).toLocaleUpperCase()
  const eventType = getSeriesEventType(seriesTicker)
  const withoutEvent = eventType === 'GERAL' ? seriesTicker : seriesTicker.slice(0, -eventType.length)
  return withoutEvent.replace(/\d+$/, '')
}

export const getEventTicker = (marketTicker: string) => {
  const segments = marketTicker.split('-')
  return segments.length > 1 ? segments.slice(0, -1).join('-') : marketTicker
}

const competitionFromSeries = (seriesTicker: string) => {
  const prefix = Object.keys(COMPETITIONS).find(key => seriesTicker.startsWith(key))
  return prefix ? COMPETITIONS[prefix] : seriesTicker.replace(/^KX/, '')
}

const cleanMatchup = (value: string) => value
  .replace(/^Map\s+\d+:\s*/i, '')
  .replace(/\s*\([^)]*\)\s*$/, '')
  .replace(/\bvs\.\s*/i, 'vs ')
  .replace(/\s+/g, ' ')
  .trim()

export const formatMetadataName = (metadata: Omit<EventMetadata, 'friendlyName' | 'fetchedAt'>) => {
  if (metadata.eventTicker === 'KXDOTA2MAP-26JUL190930PARIBB-3') return 'Dota 2: PARI vs BB — Map 3 Winner'
  const competition = metadata.competition || competitionFromSeries(getSeriesTicker(metadata.eventTicker))
  const officialMatchup = metadata.title.replace(/\s*:\s*(?:Map|Game)\s*\d*\s*$/i, '').trim()
  const matchup = cleanMatchup(/\bvs\.?\b/i.test(officialMatchup) ? officialMatchup : metadata.subTitle || metadata.title)
  const scope = metadata.competitionScope || (getSeriesTicker(metadata.eventTicker).includes('MAP') ? 'Map Winner' : 'Game Winner')
  return `${competition}: ${matchup} — ${scope}`
}

const extractMatchSlug = (eventTicker: string) => {
  const second = eventTicker.split('-')[1] ?? ''
  return second.replace(/^\d{2}[A-Z]{3}\d{6}/, '')
}

const participantCodes = (eventTicker: string, marketTickers: string[]) => {
  const slug = extractMatchSlug(eventTicker)
  const suffixes = Array.from(new Set(marketTickers
    .map(ticker => ticker.split('-').at(-1) ?? '')
    .filter(Boolean)))

  if (suffixes.length >= 2) {
    return suffixes.slice(0, 2).sort((a, b) => slug.indexOf(a) - slug.indexOf(b))
  }

  const known = suffixes[0]
  if (known && slug.includes(known)) {
    const other = slug.replace(known, '')
    if (other) {
      return slug.startsWith(known) ? [known, other] : [other, known]
    }
  }

  return slug ? [slug] : []
}

export const formatTickerName = (eventTicker: string, marketTickers: string[] = []) => {
  const seriesTicker = getSeriesTicker(eventTicker)
  const competition = competitionFromSeries(seriesTicker)
  const mapNumber = /^\d+$/.test(eventTicker.split('-').at(-1) ?? '')
    ? eventTicker.split('-').at(-1)
    : null
  const participants = participantCodes(eventTicker, marketTickers)
  const matchup = participants.length >= 2 ? `${participants[0]} vs ${participants[1]}` : participants[0] || eventTicker
  const scope = mapNumber ? `Map ${mapNumber} Winner` : seriesTicker.includes('MAP') ? 'Map Winner' : 'Game Winner'
  return `${competition}: ${matchup} — ${scope}`
}
