import Papa from 'papaparse'
import {
  CSV_COLUMNS,
  type Activity,
  type CashActivity,
  type OrderActivity,
  type ParseIssue,
  type ParseOutcome,
  type RawActivityRow,
  type SettlementActivity,
  type TradeActivity
} from './types'
import { getEventTicker, getSeriesTicker } from './ticker'

const encoder = new TextEncoder()

export const sha256 = async (value: string) => {
  const digest = await crypto.subtle.digest('SHA-256', encoder.encode(value))
  return Array.from(new Uint8Array(digest)).map(byte => byte.toString(16).padStart(2, '0')).join('')
}

const hashRows = async (values: string[], batchSize = 64) => {
  const hashes: string[] = []
  for (let index = 0; index < values.length; index += batchSize) {
    hashes.push(...await Promise.all(values.slice(index, index + batchSize).map(sha256)))
  }
  return hashes
}

const numberValue = (value: string) => {
  const normalized = (value || '0').replace(/,/g, '').trim()
  const parsed = Number(normalized)
  return Number.isFinite(parsed) ? parsed : Number.NaN
}

const canonicalRow = (row: RawActivityRow) => CSV_COLUMNS.map(column => row[column] ?? '').join('\u001f')

const parseBase = (row: RawActivityRow, id: string) => {
  const marketTicker = row.Market_Ticker.trim()
  return {
    id,
    originalDate: row.Original_Date.trim(),
    marketTicker,
    eventTicker: getEventTicker(marketTicker),
    seriesTicker: getSeriesTicker(marketTicker),
    marketId: row.Market_Id.trim(),
    raw: row
  }
}

const validateCommon = (row: RawActivityRow, rowNumber: number): ParseIssue[] => {
  const issues: ParseIssue[] = []
  const marketActivity = ['Trade', 'Order', 'Settlement'].includes(row.type)
  if (marketActivity && !row.Market_Ticker?.trim()) issues.push({ row: rowNumber, message: 'Market_Ticker está vazio' })
  if (!row.Original_Date || Number.isNaN(Date.parse(row.Original_Date))) issues.push({ row: rowNumber, message: 'Original_Date é inválida' })
  if (!['Trade', 'Order', 'Settlement', 'Deposit', 'Withdrawal', 'Credit'].includes(row.type)) issues.push({ row: rowNumber, message: `Tipo não suportado: ${row.type || 'vazio'}` })
  return issues
}

const toActivity = (row: RawActivityRow, id: string, rowNumber: number): { activity?: Activity, issues: ParseIssue[] } => {
  const issues = validateCommon(row, rowNumber)
  if (issues.length) return { issues }
  const base = parseBase(row, id)

  if (row.type === 'Trade') {
    const amount = numberValue(row.Amount_In_Dollars)
    const fee = numberValue(row.Fee_In_Dollars)
    const priceInCents = numberValue(row.Price_In_Cents)
    if (!Number.isFinite(amount) || amount < 0) issues.push({ row: rowNumber, message: 'Amount_In_Dollars é inválido' })
    if (!Number.isFinite(fee) || fee < 0) issues.push({ row: rowNumber, message: 'Fee_In_Dollars é inválido' })
    if (!Number.isFinite(priceInCents) || priceInCents < 0 || priceInCents > 100) issues.push({ row: rowNumber, message: 'Price_In_Cents deve estar entre 0 e 100' })
    if (!['Yes', 'No'].includes(row.Direction)) issues.push({ row: rowNumber, message: 'Direction deve ser Yes ou No' })
    if (!['Maker', 'Taker'].includes(row.Order_Type)) issues.push({ row: rowNumber, message: 'Order_Type deve ser Maker ou Taker' })
    if (issues.length) return { issues }
    const activity: TradeActivity = {
      ...base,
      kind: 'Trade',
      amount,
      fee,
      direction: row.Direction as 'Yes' | 'No',
      orderType: row.Order_Type as 'Maker' | 'Taker',
      priceInCents,
      tradedTime: row.Traded_Time
    }
    return { activity, issues }
  }

  if (row.type === 'Order') {
    const filled = numberValue(row.Filled)
    const remaining = numberValue(row.Remaining)
    if (!Number.isFinite(filled) || !Number.isFinite(remaining)) issues.push({ row: rowNumber, message: 'Filled ou Remaining é inválido' })
    if (issues.length) return { issues }
    const activity: OrderActivity = {
      ...base,
      kind: 'Order',
      status: row.Status,
      filled,
      remaining
    }
    return { activity, issues }
  }

  if (['Deposit', 'Withdrawal', 'Credit'].includes(row.type)) {
    const amount = numberValue(row.Amount_In_Dollars)
    const parsedFee = numberValue(row.Fee_In_Dollars)
    if (!Number.isFinite(amount)) issues.push({ row: rowNumber, message: 'Amount_In_Dollars da movimentação é inválido' })
    if (issues.length) return { issues }
    const activity: CashActivity = {
      ...base,
      kind: row.type as CashActivity['kind'],
      amount,
      fee: Number.isFinite(parsedFee) ? parsedFee : 0,
      status: row.Status,
      depositType: row.Deposit_Type,
      reason: row.Credit_Reason
    }
    return { activity, issues }
  }

  const noOwned = numberValue(row.No_Contracts_Owned)
  const noAveragePrice = numberValue(row.No_Contracts_Average_Price_In_Cents)
  const yesOwned = numberValue(row.Yes_Contracts_Owned)
  const yesAveragePrice = numberValue(row.Yes_Contracts_Average_Price_In_Cents)
  const profit = numberValue(row.Profit_In_Dollars)
  if (![noOwned, noAveragePrice, yesOwned, yesAveragePrice, profit].every(Number.isFinite)) issues.push({ row: rowNumber, message: 'Campos numéricos da liquidação são inválidos' })
  if (!['yes', 'no', 'scalar'].includes(row.Result)) issues.push({ row: rowNumber, message: 'Result deve ser yes, no ou scalar' })
  if (issues.length) return { issues }
  const activity: SettlementActivity = {
    ...base,
    kind: 'Settlement',
    noOwned,
    noAveragePrice,
    yesOwned,
    yesAveragePrice,
    result: row.Result as 'yes' | 'no' | 'scalar',
    profit
  }
  return { activity, issues }
}

export const parseActivityCsv = async (text: string, fileName: string): Promise<ParseOutcome> => {
  const parsed = Papa.parse<RawActivityRow>(text.replace(/^\uFEFF/, ''), {
    header: true,
    skipEmptyLines: 'greedy',
    dynamicTyping: false,
    transformHeader: header => header.trim()
  })
  const fields = parsed.meta.fields ?? []
  const missing = CSV_COLUMNS.filter(column => !fields.includes(column))
  if (missing.length) throw new Error(`CSV incompatível. Colunas ausentes: ${missing.join(', ')}`)
  const extra = fields.filter(field => !CSV_COLUMNS.includes(field as typeof CSV_COLUMNS[number]))
  const warnings = extra.length ? [`Colunas extras ignoradas: ${extra.join(', ')}`] : []
  const issues: ParseIssue[] = parsed.errors.map(error => ({ row: error.row === undefined ? undefined : error.row + 2, message: error.message }))

  const canonicals = parsed.data.map(canonicalRow)
  const uniqueCanonicals = Array.from(new Set(canonicals))
  const hashes = await hashRows(uniqueCanonicals)
  const hashByCanonical = new Map(uniqueCanonicals.map((value, index) => [value, hashes[index]]))
  const occurrences = new Map<string, number>()
  const activities: Activity[] = []

  parsed.data.forEach((row, index) => {
    const canonical = canonicals[index]
    const hash = hashByCanonical.get(canonical) ?? ''
    const ordinal = (occurrences.get(hash) ?? 0) + 1
    occurrences.set(hash, ordinal)
    const result = toActivity(row, `${hash}:${ordinal}`, index + 2)
    issues.push(...result.issues)
    if (result.activity) activities.push(result.activity)
  })

  return {
    fileHash: await sha256(text),
    fileName,
    importedAt: new Date().toISOString(),
    activities,
    validRows: activities.length,
    rejectedRows: parsed.data.length - activities.length,
    warnings,
    issues
  }
}

export const mergeSnapshots = (snapshots: ParseOutcome[]) => {
  const activities = new Map<string, Activity>()
  snapshots.forEach(snapshot => snapshot.activities.forEach(activity => activities.set(activity.id, activity)))
  return Array.from(activities.values()).sort((a, b) => Date.parse(a.originalDate) - Date.parse(b.originalDate))
}
