import Decimal from 'decimal.js'
import type { PolymarketImport } from './polymarket'
import { CSV_COLUMNS, type Activity, type ActivityBase, type EvaluatedTrade, type EventMetadata, type PositionChangeActivity, type RawActivityRow, type SettlementResult, type TradeActivity, type TradeRealization } from './types'

const decimal = (value: Decimal.Value) => new Decimal(value)
const numeric = (value: Decimal) => value.toDecimalPlaces(8).toNumber()
const finite = (value: unknown) => Number.isFinite(Number(value)) ? Number(value) : 0
const validNumber = (value: unknown) => (typeof value === 'number' || (typeof value === 'string' && value.trim() !== '')) && Number.isFinite(Number(value))
const string = (value: unknown) => typeof value === 'string' ? value : ''
const list = (value: unknown): unknown[] => {
  if (Array.isArray(value)) return value
  try { const parsed = JSON.parse(string(value)); return Array.isArray(parsed) ? parsed : [] } catch { return [] }
}
const iso = (value: unknown) => {
  const time = typeof value === 'number' ? value * 1000 : Date.parse(string(value))
  return Number.isFinite(time) ? new Date(time).toISOString() : null
}
const marketKey = (conditionId: string) => `POLY:${conditionId.toLowerCase()}`
const positionKey = (activity: ActivityBase) => `${activity.accountId}:${activity.marketTicker}:${activity.tokenId ?? activity.outcome}`
const inventoryMarketKey = (activity: ActivityBase) => `${activity.accountId}:${activity.marketTicker}`

/** Public activity has no execution fee or liquidity-role fields. Zero is only a
 * numeric placeholder; feesKnown=false and the persistent warning preserve this. */
export const normalizePolymarketImport = (input: PolymarketImport): { activities: Activity[]; metadata: EventMetadata[]; warnings: string[] } => {
  const activities: Activity[] = []
  const warnings = new Set(input.warnings)
  const markets = new Map(input.markets.map(market => [string(market.conditionId).toLowerCase(), market]))
  const metadata = new Map<string, EventMetadata>()
  const occurrences = new Map<string, number>()
  const wallet = input.account.address.toLowerCase()
  warnings.add('Polymarket: a API pública não informa taxas por execução nem Maker/Taker. O PnL exibido não desconta taxas desconhecidas; FIFO é calculado separadamente por conta e token.')

  for (const item of input.activities) {
    const date = iso(item.timestamp)
    if (!date) { warnings.add('Polymarket: atividade sem data válida foi ignorada.'); continue }
    const conditionId = string(item.conditionId).toLowerCase()
    const market = markets.get(conditionId)
    const outcomes = list(market?.outcomes).map(String)
    const tokens = list(market?.clobTokenIds).map(String)
    const outcomeIndex = Number(item.outcomeIndex)
    let tokenId = string(item.asset) || (item.type !== 'REDEEM' && Number.isInteger(outcomeIndex) ? tokens[outcomeIndex] ?? '' : '')
    if (!tokenId && item.type === 'REDEEM' && market?.closed && string(market.umaResolutionStatus).toLowerCase() === 'resolved') {
      const prices = list(market.outcomePrices).map(Number)
      const winners = prices.map((price, index) => ({ price, index })).filter(value => value.price > 0)
      // Legacy aggregate REDEEM rows can contain a meaningless outcomeIndex.
      // Infer the winning token only from a verified, unambiguous final result.
      if (finite(item.usdcSize) > 0 && winners.length === 1 && winners[0].price === 1) tokenId = tokens[winners[0].index] ?? ''
    }
    const outcome = string(item.outcome) || (Number.isInteger(outcomeIndex) ? outcomes[outcomeIndex] ?? '' : '')
    const eventSlug = string(item.eventSlug) || string(item.slug) || conditionId
    const ticker = marketKey(conditionId)
    const eventTicker = `POLY:${eventSlug}`
    const serialized = JSON.stringify([item.timestamp, item.type, conditionId, item.transactionHash, item.asset, item.side, item.outcomeIndex, item.size, item.usdcSize, item.price])
    const ordinal = occurrences.get(serialized) ?? 0
    occurrences.set(serialized, ordinal + 1)
    const raw = Object.assign(Object.fromEntries(CSV_COLUMNS.map(column => [column, ''])), Object.fromEntries(Object.entries(item).map(([key, value]) => [key, typeof value === 'string' ? value : JSON.stringify(value) ?? '']))) as RawActivityRow
    const base: ActivityBase = {
      id: `polymarket:${wallet}:${serialized}:${ordinal}`, kind: 'Trade', source: 'polymarket', accountId: input.account.id, accountName: input.account.name,
      originalDate: date, marketTicker: conditionId ? ticker : '', eventTicker: conditionId ? eventTicker : '', seriesTicker: 'POLYMARKET', marketId: conditionId,
      marketSlug: string(item.slug) || string(market?.slug), tokenId, outcome, raw
    }
    const amount = finite(item.size)
    // Non-trade activity (for example REWARD) reports its cash value as
    // `amount`, while trades use `usdcSize`. Preserve either representation.
    const cashAmount = item.type === 'TRADE'
      ? finite(item.usdcSize)
      : validNumber(item.amount) ? finite(item.amount) : finite(item.usdcSize)
    if (item.type === 'TRADE') {
      if (!tokenId || !validNumber(item.size) || !(amount > 0) || !validNumber(item.usdcSize) || cashAmount < 0 || !validNumber(item.price) || !['BUY', 'SELL'].includes(string(item.side)) || finite(item.price) < 0 || finite(item.price) > 1) {
        warnings.add(`Polymarket: trade inválido em ${string(item.slug) || conditionId}; não incluído nos totais.`)
        continue
      }
      const direction = outcomeIndex === 1 || outcome.toLocaleLowerCase() === 'no' ? 'No' : 'Yes'
      activities.push({ ...base, kind: 'Trade', amount, cashAmount, fee: 0, feesKnown: false, side: item.side as 'BUY' | 'SELL', direction, orderType: 'Unknown', priceInCents: finite(item.price) * 100, tradedTime: date,
        ...(item.isCombo ? { accountingWarning: 'Combo sem composição/custo completo na API pública; excluído de PnL e capital aberto.' } : {}) })
    } else if (['REDEEM', 'SPLIT', 'MERGE', 'CONVERSION'].includes(item.type)) {
      const operation = item.type as PositionChangeActivity['operation']
      const accountingWarning = operation !== 'REDEEM'
        ? `${operation}: movimentos de inventário sem base de custo completa; mercado excluído de PnL e capital aberto.`
        : !tokenId ? 'REDEEM sem token identificável; mercado excluído de PnL e capital aberto.' : undefined
      activities.push({ ...base, kind: 'PositionChange', operation, amount, cashAmount, accountingWarning })
      if (accountingWarning) warnings.add(`Polymarket · ${input.account.name} · ${string(item.slug) || conditionId}: ${accountingWarning}`)
    } else if (['DEPOSIT', 'WITHDRAWAL'].includes(item.type)) {
      const kind = item.type === 'DEPOSIT' ? 'Deposit' : 'Withdrawal'
      activities.push({ ...base, kind, amount: cashAmount, fee: 0, status: 'Applied', depositType: '', reason: item.type })
    } else if (['CREDIT', 'REWARD', 'REBATE', 'MAKER_REBATE', 'TAKER_REBATE', 'LIQUIDITY_REWARD', 'YIELD', 'REFERRAL', 'REFERRAL_REWARD'].includes(item.type)) {
      activities.push({ ...base, kind: 'Credit', amount: cashAmount, fee: 0, status: 'Applied', depositType: '', reason: item.type })
    } else {
      warnings.add(`Polymarket: atividade ${item.type} preservada, sem efeito financeiro inferido.`)
      activities.push({ ...base, kind: 'PositionChange', operation: 'UNSUPPORTED', amount, cashAmount, accountingWarning: `Atividade ${item.type} não contabilizada; custo do mercado não verificável.` })
    }
    if (conditionId) {
      const entry = metadata.get(eventTicker) ?? {
        source: 'polymarket' as const, eventTicker, title: string(item.title) || string(market?.question) || eventSlug,
        subTitle: '', competition: 'Polymarket', competitionScope: '', markets: [], friendlyName: string(item.title) || string(market?.question) || eventSlug, fetchedAt: input.syncedAt
      }
      if (!entry.markets.some(value => value.ticker === ticker)) entry.markets.push({ ticker, title: string(item.title) || string(market?.question) || conditionId, yesSubTitle: outcomes[0] ?? '', noSubTitle: outcomes[1] ?? '', result: '', settlementValue: null, status: market?.closed ? 'closed' : 'open', settlementAt: null })
      metadata.set(eventTicker, entry)
    }
  }

  // Only a final oracle result is a settlement. A closed orderbook or a price
  // close to 1 is insufficient evidence, and endDate is not a settlement date.
  for (const [conditionId, market] of markets) {
    if (!market.closed || string(market.umaResolutionStatus).toLowerCase() !== 'resolved') continue
    const tokens = list(market.clobTokenIds).map(String)
    const outcomes = list(market.outcomes).map(String)
    const prices = list(market.outcomePrices).map(Number)
    if (tokens.length < 2 || prices.length !== tokens.length || !prices.every(value => Number.isFinite(value) && value >= 0 && value <= 1) || Math.abs(prices.reduce((total, value) => total + value, 0) - 1) > 1e-8) continue
    const reference = activities.find(activity => activity.marketId === conditionId && activity.kind === 'Trade')
    if (!reference) continue
    const settlementDate = iso(market.closedTime)
    if (!settlementDate) { warnings.add(`Polymarket: ${reference.marketSlug || conditionId} está resolvido, mas sem data verificável; resgates efetivos continuam contabilizados.`); continue }
    const result: SettlementResult = tokens.length === 2
      ? prices[0] === 1 ? 'yes' : prices[1] === 1 ? 'no' : 'scalar'
      : 'scalar'
    tokens.forEach((tokenId, index) => activities.push({ ...reference, id: `polymarket:${wallet}:resolution:${conditionId}:${tokenId}`, kind: 'PositionChange', originalDate: settlementDate, tokenId, outcome: outcomes[index], operation: 'RESOLUTION', amount: 0, cashAmount: 0, outcomeValue: prices[index], result }))
    for (const entry of metadata.values()) for (const value of entry.markets) if (value.ticker === reference.marketTicker) Object.assign(value, { result, settlementValue: prices[0], settlementAt: settlementDate })
  }

  const evaluated = evaluatePolymarketTrades(activities)
  for (const trade of evaluated.values()) if (trade.accountingWarning) warnings.add(`Polymarket · ${input.account.name} · ${trade.marketSlug || trade.marketTicker}: ${trade.accountingWarning}`)
  // A transfer into/out of the wallet is not necessarily present in /activity.
  // Reconcile remaining quantities with the separately downloaded positions.
  const expected = new Map<string, number>()
  for (const trade of evaluated.values()) if (trade.side === 'BUY' && !trade.accountingWarning) expected.set(trade.tokenId!, (expected.get(trade.tokenId!) ?? 0) + (trade.openAmount ?? 0))
  for (const position of input.positions) {
    if (position.redeemable) continue
    const token = string(position.asset)
    const difference = Math.abs((expected.get(token) ?? 0) - finite(position.size))
    if (difference > 0.0001) warnings.add(`Polymarket · ${input.account.name}: posição ${string(position.title) || token} difere do histórico em ${numeric(decimal(difference))} contratos; transferências ou atividades ainda não indexadas podem deixar o custo incompleto.`)
    expected.delete(token)
  }
  for (const [token, amount] of expected) if (amount > 0.0001) warnings.add(`Polymarket · ${input.account.name}: ${amount} contratos de ${token} não aparecem nas posições atuais; capital aberto pode estar incompleto.`)
  return { activities, metadata: Array.from(metadata.values()), warnings: Array.from(warnings) }
}

interface Lot { trade: EvaluatedTrade; amount: Decimal; unitCost: Decimal; unitFee: Decimal }

/** FIFO must receive the complete, unfiltered history; account+token is the
 * inventory identity even when the dashboard groups the same market together. */
export const evaluatePolymarketTrades = (activities: Activity[]): Map<string, EvaluatedTrade> => {
  const result = new Map<string, EvaluatedTrade>()
  const inventories = new Map<string, Lot[]>()
  const invalidMarkets = new Map<string, string>()
  const invalidAccounts = new Map<string, string>()
  const relevant = activities.filter(activity => activity.source === 'polymarket')
  for (const activity of relevant) {
    if ((activity.kind === 'Trade' || activity.kind === 'PositionChange') && activity.accountingWarning) invalidMarkets.set(inventoryMarketKey(activity), activity.accountingWarning)
    if (activity.kind === 'PositionChange' && activity.operation === 'CONVERSION') invalidAccounts.set(activity.accountId ?? '', 'CONVERSION afeta tokens de vários mercados; conta excluída de PnL e capital aberto por custo incompleto.')
  }
  const ordered = relevant.filter(activity => activity.kind !== 'PositionChange' || activity.operation !== 'RESOLUTION').sort((a, b) => Date.parse(a.originalDate) - Date.parse(b.originalDate))
  // Actual cash redemptions take priority; final-resolution events only realize
  // the inventory still held, avoiding double-counting redemption proceeds.
  ordered.push(...relevant.filter(activity => activity.kind === 'PositionChange' && activity.operation === 'RESOLUTION'))

  const record = (trade: EvaluatedTrade, realization: TradeRealization) => {
    trade.realizations!.push(realization)
    trade.realizedCost = numeric(decimal(trade.realizedCost!).plus(realization.cost))
    trade.realizedFees = numeric(decimal(trade.realizedFees!).plus(realization.fees))
    trade.payout = numeric(decimal(trade.payout ?? 0).plus(realization.payout))
    trade.grossPnl = numeric(decimal(trade.grossPnl ?? 0).plus(realization.grossPnl))
    trade.netPnl = numeric(decimal(trade.netPnl ?? 0).plus(realization.netPnl))
    trade.settlementDate = realization.date
  }
  const consume = (key: string, requested: Decimal) => {
    let remaining = requested
    const consumed: Array<{ lot: Lot; amount: Decimal; cost: Decimal; fee: Decimal }> = []
    const lots = inventories.get(key) ?? []
    // Never mutate FIFO inventory when a sell/redeem asks for more than the
    // known balance. A partial mutation would make later valid trades appear
    // to have no cost and would silently understate open capital.
    const available = lots.reduce((total, lot) => total.plus(lot.amount), decimal(0))
    if (requested.gt(available.plus(0.00000001))) return { consumed: [], missing: true }
    for (const lot of lots) {
      if (remaining.lte(0)) break
      const amount = Decimal.min(lot.amount, remaining)
      if (amount.lte(0)) continue
      consumed.push({ lot, amount, cost: amount.times(lot.unitCost), fee: amount.times(lot.unitFee) })
      lot.amount = lot.amount.minus(amount)
      remaining = remaining.minus(amount)
      lot.trade.openAmount = numeric(lot.amount)
      lot.trade.openCost = numeric(lot.amount.times(lot.unitCost.plus(lot.unitFee)))
      lot.trade.settled = lot.amount.lte(0.00000001)
    }
    inventories.set(key, lots.filter(lot => lot.amount.gt(0)))
    return { consumed, missing: remaining.gt(0.00000001) }
  }

  for (const activity of ordered) {
    if (activity.kind !== 'Trade' && activity.kind !== 'PositionChange') continue
    const key = positionKey(activity)
    const warning = invalidAccounts.get(activity.accountId ?? '') || invalidMarkets.get(inventoryMarketKey(activity))
    if (activity.kind === 'Trade') {
      const cost = activity.cashAmount ?? numeric(decimal(activity.amount).times(activity.priceInCents).div(100))
      const evaluated: EvaluatedTrade = { ...activity, effectivePrice: activity.priceInCents, cost, payout: null, grossPnl: null, netPnl: null, settled: false, settlementDate: null, settlementValue: null, result: null,
        realizedCost: 0, realizedFees: 0, capitalInvested: activity.side === 'SELL' ? 0 : cost, openCost: 0, openAmount: 0, realizations: [], ...(warning ? { accountingWarning: warning } : {}) }
      result.set(activity.id, evaluated)
      if (warning) continue
      if (activity.side !== 'SELL') {
        evaluated.openAmount = activity.amount
        evaluated.openCost = cost + activity.fee
        const lots = inventories.get(key) ?? []
        lots.push({ trade: evaluated, amount: decimal(activity.amount), unitCost: decimal(cost).div(activity.amount), unitFee: decimal(activity.fee).div(activity.amount) })
        inventories.set(key, lots)
      } else {
        const { consumed, missing } = consume(key, decimal(activity.amount))
        if (missing) { evaluated.accountingWarning = 'Venda sem quantidade/custo de compra suficiente no histórico desta conta; PnL da venda não calculado.'; continue }
        const basis = consumed.reduce((total, item) => total.plus(item.cost), decimal(0))
        const fees = consumed.reduce((total, item) => total.plus(item.fee), decimal(activity.fee))
        const gross = decimal(cost).minus(basis)
        evaluated.cost = numeric(basis)
        evaluated.settled = true
        record(evaluated, { date: activity.originalDate, amount: activity.amount, cost: numeric(basis), fees: numeric(fees), payout: cost, grossPnl: numeric(gross), netPnl: numeric(gross.minus(fees)) })
      }
    } else if (!warning && ['REDEEM', 'RESOLUTION'].includes(activity.operation)) {
      const lots = inventories.get(key) ?? []
      const available = lots.reduce((total, lot) => total.plus(lot.amount), decimal(0))
      const requested = activity.operation === 'RESOLUTION' ? available : decimal(activity.amount)
      if (requested.lte(0)) continue
      const { consumed, missing } = consume(key, requested)
      if (missing) {
        for (const { lot } of consumed) lot.trade.accountingWarning = 'Resgate excede o inventário conhecido; PnL do resgate não calculado.'
        continue
      }
      const unitPayout = activity.operation === 'RESOLUTION' ? decimal(activity.outcomeValue ?? 0) : decimal(activity.cashAmount).div(requested)
      for (const { lot, amount, cost, fee } of consumed) {
        const payout = amount.times(unitPayout)
        const gross = payout.minus(cost)
        record(lot.trade, { date: activity.originalDate, amount: numeric(amount), cost: numeric(cost), fees: numeric(fee), payout: numeric(payout), grossPnl: numeric(gross), netPnl: numeric(gross.minus(fee)) })
        lot.trade.settlementValue = numeric(unitPayout)
        lot.trade.result = activity.result ?? (unitPayout.eq(0) ? (lot.trade.direction === 'Yes' ? 'no' : 'yes') : unitPayout.eq(1) ? (lot.trade.direction === 'Yes' ? 'yes' : 'no') : 'scalar')
      }
    }
  }

  // A position may be sold before the oracle resolves the market. Its sale PnL
  // is already final, but the market result is still useful for the result
  // filter and for presenting the same context as a Kalshi settlement.
  const resolutions = new Map<string, { value: number, result?: SettlementResult }>()
  for (const activity of relevant) {
    if (activity.kind !== 'PositionChange' || activity.operation !== 'RESOLUTION' || !activity.tokenId) continue
    resolutions.set(positionKey(activity), { value: activity.outcomeValue ?? 0, result: activity.result })
  }
  for (const trade of result.values()) {
    if (trade.result || !trade.tokenId) continue
    const resolution = resolutions.get(positionKey(trade))
    if (resolution) {
      trade.settlementValue = resolution.value
      trade.result = resolution.result ?? (resolution.value === 1 ? 'yes' : resolution.value === 0 ? 'no' : 'scalar')
    }
  }
  return result
}
