export const CSV_COLUMNS = [
  'type',
  'Status',
  'Amount_In_Dollars',
  'Original_Date',
  'Traded_Time',
  'Last_Updated',
  'Deposit_Type',
  'Fee_In_Dollars',
  'Market_Title',
  'Market_Ticker',
  'Market_Id',
  'Filled',
  'Remaining',
  'Direction',
  'Order_Type',
  'Price_In_Cents',
  'No_Contracts_Owned',
  'No_Contracts_Average_Price_In_Cents',
  'Yes_Contracts_Owned',
  'Yes_Contracts_Average_Price_In_Cents',
  'Result',
  'Profit_In_Dollars',
  'Credit_Reason',
  'Credit_Type',
  'Introducing_Broker'
] as const

export type CsvColumn = (typeof CSV_COLUMNS)[number]
export type RawActivityRow = Record<CsvColumn, string> & Record<string, string>
export type ActivityKind = 'Trade' | 'Order' | 'Settlement' | 'Deposit' | 'Withdrawal' | 'Credit' | 'PositionChange'
export type Direction = 'Yes' | 'No'
export type LiquidityRole = 'Maker' | 'Taker' | 'Unknown'
export type ActivitySource = 'kalshi' | 'polymarket'
export type SettlementResult = 'yes' | 'no' | 'scalar'
export type CalendarBasis = 'tradeDate' | 'settlementDate'
export type ViewName = 'overview' | 'calendar' | 'history'

export interface ActivityBase {
  source?: ActivitySource
  accountId?: string
  accountName?: string
  marketSlug?: string
  tokenId?: string
  outcome?: string
  id: string
  kind: ActivityKind
  originalDate: string
  marketTicker: string
  eventTicker: string
  seriesTicker: string
  marketId: string
  raw: RawActivityRow
}

export interface TradeActivity extends ActivityBase {
  kind: 'Trade'
  amount: number
  fee: number
  direction: Direction
  orderType: LiquidityRole
  priceInCents: number
  tradedTime: string
  side?: 'BUY' | 'SELL'
  feesKnown?: boolean
  accountingWarning?: string
  cashAmount?: number
}

export interface PositionChangeActivity extends ActivityBase {
  kind: 'PositionChange'
  operation: 'REDEEM' | 'RESOLUTION' | 'SPLIT' | 'MERGE' | 'CONVERSION' | 'UNSUPPORTED'
  amount: number
  cashAmount: number
  outcomeValue?: number
  result?: SettlementResult
  accountingWarning?: string
}

export interface OrderActivity extends ActivityBase {
  kind: 'Order'
  status: string
  filled: number
  remaining: number
}

export interface SettlementActivity extends ActivityBase {
  kind: 'Settlement'
  noOwned: number
  noAveragePrice: number
  yesOwned: number
  yesAveragePrice: number
  result: SettlementResult
  profit: number
}

export interface CashActivity extends ActivityBase {
  kind: 'Deposit' | 'Withdrawal' | 'Credit'
  amount: number
  fee: number
  status: string
  depositType: string
  reason: string
}

export type Activity = TradeActivity | OrderActivity | SettlementActivity | CashActivity | PositionChangeActivity

export interface SettlementFallback {
  marketTicker: string
  result: SettlementResult
  settlementValue: number
  settlementDate: string
  source: 'kalshi-api'
}

export interface ParseIssue {
  row?: number
  message: string
}

export interface ParseOutcome {
  fileHash: string
  fileName: string
  importedAt: string
  activities: Activity[]
  validRows: number
  rejectedRows: number
  warnings: string[]
  issues: ParseIssue[]
}

export interface Snapshot extends ParseOutcome {}

export interface AnalysisFilterState {
  dateBasis: CalendarBasis
  query: string
  dateFrom: string
  dateTo: string
  series: string
  event: string
  market: string
  direction: Direction | ''
  role: LiquidityRole | ''
  result: SettlementResult | ''
  priceMin: string
  priceMax: string
}

export interface EvaluatedTrade extends TradeActivity {
  effectivePrice: number
  cost: number
  payout: number | null
  grossPnl: number | null
  netPnl: number | null
  settled: boolean
  settlementValue: number | null
  settlementDate: string | null
  result: SettlementResult | null
  realizedCost?: number
  realizedFees?: number
  capitalInvested?: number
  openCost?: number
  openAmount?: number
  realizations?: TradeRealization[]
}

export interface TradeRealization {
  date: string
  amount: number
  cost: number
  fees: number
  payout: number
  grossPnl: number
  netPnl: number
}

export interface Breakdown {
  key: string
  label: string
  trades: number
  volume: number
  cost: number
  totalCost: number
  fees: number
  realizedFees: number
  settledTrades: number
  payout: number
  pnl: number
  roi: number | null
  winRate: number | null
}

export interface MarketAggregate extends Breakdown {
  source?: ActivitySource
  openCapital?: number
  marketTicker: string
  eventTicker: string
  seriesTicker: string
  firstTrade: string
  lastTrade: string
  settlementDate: string | null
  result: SettlementResult | null
  settled: boolean
  holdMinutes: number | null
}

export interface EventAggregate extends Breakdown {
  eventTicker: string
  seriesTicker: string
  marketCount: number
  firstTrade: string
  lastTrade: string
  markets: MarketAggregate[]
  activities: Activity[]
}

export interface DailyAggregate {
  pendingTrades?: number
  date: string
  pnl: number
  grossPnl: number
  fees: number
  trades: number
  settledTrades: number
  markets: number
  cumulativePnl: number
}

export interface PriceBucket extends Breakdown {
  min: number
  max: number
}

export interface CompactPosition extends Breakdown {
  source?: ActivitySource
  outcome?: string
  marketSlug?: string
  marketTicker: string
  eventTicker: string
  direction: Direction
  averagePrice: number
  firstTrade: string
  lastTrade: string
  result: SettlementResult | null
}

export interface AnalysisSummary {
  trades: number
  orders: number
  settlements: number
  markets: number
  events: number
  volume: number
  cost: number
  totalCost: number
  fees: number
  realizedFees: number
  payout: number
  grossPnl: number
  netPnl: number
  roi: number | null
  pnlToVolume: number | null
  marketWinRate: number | null
  profitFactor: number | null
  weightedEntryPrice: number | null
  feeRate: number | null
  averageFill: number | null
  medianFill: number | null
  holdMinutes: number | null
  non99Roi: number | null
  topFiveConcentration: number | null
  openCapital: number
  openMarkets: number
  positiveFills: number
  negativeFills: number
  deposits: number
  withdrawals: number
  credits: number
  netCashFlow: number
}

export interface AnalysisResult {
  warnings?: string[]
  summary: AnalysisSummary
  activities: Activity[]
  trades: EvaluatedTrade[]
  markets: MarketAggregate[]
  events: EventAggregate[]
  dailyTrade: DailyAggregate[]
  dailySettlement: DailyAggregate[]
  calendarTrade: DailyAggregate[]
  calendarSettlement: DailyAggregate[]
  priceBuckets: PriceBucket[]
  byDirection: Breakdown[]
  byRole: Breakdown[]
  compactPositions: CompactPosition[]
  series: Breakdown[]
}

export interface KalshiMarketMetadata {
  ticker: string
  title: string
  yesSubTitle: string
  noSubTitle: string
  result: string
  settlementValue: number | null
  status: string
  settlementAt: string | null
}

export interface EventMetadata {
  source?: ActivitySource
  eventTicker: string
  title: string
  subTitle: string
  competition: string
  competitionScope: string
  markets: KalshiMarketMetadata[]
  friendlyName: string
  fetchedAt: string
}

export const EMPTY_FILTERS: AnalysisFilterState = {
  dateBasis: 'tradeDate',
  query: '',
  dateFrom: '',
  dateTo: '',
  series: '',
  event: '',
  market: '',
  direction: '',
  role: '',
  result: '',
  priceMin: '',
  priceMax: ''
}
