import Decimal from 'decimal.js'
import {
  EMPTY_FILTERS,
  type Activity,
  type AnalysisFilterState,
  type AnalysisResult,
  type Breakdown,
  type CashActivity,
  type CompactPosition,
  type DailyAggregate,
  type EvaluatedTrade,
  type EventAggregate,
  type MarketAggregate,
  type PriceBucket,
  type SettlementActivity,
  type SettlementFallback,
  type TradeActivity
} from './types'
import { getSeriesEventType, getSeriesFamily } from './ticker'
import { evaluatePolymarketTrades } from './polymarketAccounting'

const TIME_ZONE = 'America/Sao_Paulo'
const dateFormatter = new Intl.DateTimeFormat('en-CA', {
  timeZone: TIME_ZONE,
  year: 'numeric',
  month: '2-digit',
  day: '2-digit'
})

const n = (value: Decimal.Value) => new Decimal(value)
const number = (value: Decimal) => value.toDecimalPlaces(8).toNumber()
const sum = (values: Array<number | null | undefined>) => number(values.reduce<Decimal>((total, value) => total.plus(value ?? 0), n(0)))
const ratio = (numerator: number, denominator: number) => denominator ? numerator / denominator : null
const byDate = (value: string) => Date.parse(value)

export const localDate = (value: string) => {
  const parts = dateFormatter.formatToParts(new Date(value))
  const get = (type: Intl.DateTimeFormatPartTypes) => parts.find(part => part.type === type)?.value ?? ''
  return `${get('year')}-${get('month')}-${get('day')}`
}

export const effectivePrice = (trade: TradeActivity) => trade.source === 'polymarket' || trade.direction === 'Yes'
  ? trade.priceInCents
  : 100 - trade.priceInCents

export const settlementValue = (settlement: SettlementActivity) => {
  if (settlement.result === 'yes') return 1
  if (settlement.result === 'no') return 0
  const netYes = n(settlement.yesOwned).minus(settlement.noOwned)
  if (netYes.gt(0)) return Decimal.min(1, Decimal.max(0, n(settlement.profit).div(netYes))).toNumber()
  const netNo = n(settlement.noOwned).minus(settlement.yesOwned)
  if (netNo.gt(0)) return Decimal.min(1, Decimal.max(0, n(1).minus(n(settlement.profit).div(netNo)))).toNumber()
  return 0.5
}

interface SettlementContext {
  result: SettlementActivity['result']
  value: number
  date: string
}

const settlementMap = (
  activities: Activity[],
  fallbacks: Record<string, SettlementFallback> = {}
) => {
  const settlements = new Map<string, SettlementContext>(Object.values(fallbacks).map(fallback => [fallback.marketTicker, {
    result: fallback.result,
    value: fallback.settlementValue,
    date: fallback.settlementDate
  }]))
  activities
    .filter((activity): activity is SettlementActivity => activity.kind === 'Settlement')
    .forEach(activity => settlements.set(activity.marketTicker, {
      result: activity.result,
      value: settlementValue(activity),
      date: activity.originalDate
    }))
  return settlements
}

export const evaluateTrades = (
  activities: Activity[],
  settlementActivities: Activity[] = activities,
  fallbacks: Record<string, SettlementFallback> = {}
) => {
  const settlements = settlementMap(settlementActivities, fallbacks)
  const contextIds = new Set(settlementActivities.map(activity => activity.id))
  const polymarket = evaluatePolymarketTrades(settlementActivities === activities ? activities : [...settlementActivities, ...activities.filter(activity => !contextIds.has(activity.id))])
  return activities
    .filter((activity): activity is TradeActivity => activity.kind === 'Trade')
    .map<EvaluatedTrade>(trade => {
      if (trade.source === 'polymarket') return polymarket.get(trade.id)!
      const settlement = settlements.get(trade.marketTicker)
      const entry = effectivePrice(trade)
      const cost = n(trade.amount).times(entry).div(100)
      if (!settlement) {
        return {
          ...trade,
          effectivePrice: entry,
          cost: number(cost),
          payout: null,
          grossPnl: null,
          netPnl: null,
          settled: false,
          settlementValue: null,
          settlementDate: null,
          result: null
        }
      }
      const value = settlement.value
      const payout = n(trade.amount).times(trade.direction === 'Yes' ? value : n(1).minus(value))
      const grossPnl = payout.minus(cost)
      return {
        ...trade,
        effectivePrice: entry,
        cost: number(cost),
        payout: number(payout),
        grossPnl: number(grossPnl),
        netPnl: number(grossPnl.minus(trade.fee)),
        settled: true,
        settlementValue: value,
        settlementDate: settlement.date,
        result: settlement.result
      }
    })
}

const matchesCommonFilters = (
  activity: Activity,
  filters: AnalysisFilterState,
  friendlyNames: Record<string, string>
) => {
  const query = filters.query.trim().toLocaleLowerCase('pt-BR')
  const haystack = [
    activity.marketTicker,
    activity.eventTicker,
    activity.seriesTicker,
    activity.marketSlug ?? '',
    activity.accountName ?? '',
    activity.outcome ?? '',
    friendlyNames[activity.eventTicker] ?? ''
  ].join(' ').toLocaleLowerCase('pt-BR')
  const date = localDate(activity.originalDate)
  if (query && !haystack.includes(query)) return false
  if (filters.dateBasis === 'tradeDate' && filters.dateFrom && date < filters.dateFrom) return false
  if (filters.dateBasis === 'tradeDate' && filters.dateTo && date > filters.dateTo) return false
  if (filters.series && getSeriesFamily(activity.seriesTicker) !== filters.series) return false
  if (filters.event && getSeriesEventType(activity.seriesTicker) !== filters.event) return false
  if (filters.market && activity.marketTicker !== filters.market) return false
  return true
}

const matchesTradeFilters = (trade: TradeActivity, filters: AnalysisFilterState) => {
  if (filters.direction && trade.direction !== filters.direction) return false
  if (filters.role && trade.orderType !== filters.role) return false
  if (filters.priceMin && effectivePrice(trade) < Number(filters.priceMin)) return false
  if (filters.priceMax && effectivePrice(trade) > Number(filters.priceMax)) return false
  return true
}

const intersect = (left: Set<string>, right: Set<string>) => new Set(Array.from(left).filter(value => right.has(value)))

const filterKalshiActivities = (
  activities: Activity[],
  filters: AnalysisFilterState = EMPTY_FILTERS,
  friendlyNames: Record<string, string> = {},
  fallbacks: Record<string, SettlementFallback> = {}
) => {
  const initiallyMatched = activities.filter(activity => matchesCommonFilters(activity, filters, friendlyNames))
  const settlements = settlementMap(activities, fallbacks)
  let markets = new Set(initiallyMatched.map(activity => activity.marketTicker).filter(Boolean))
  let marketConstraint = false
  const filteredBySettlementDate = filters.dateBasis === 'settlementDate' && Boolean(filters.dateFrom || filters.dateTo)
  if (filteredBySettlementDate) {
    marketConstraint = true
    const settlementDateMarkets = new Set(Array.from(settlements.entries())
      .filter(([, settlement]) => {
        const date = localDate(settlement.date)
        if (filters.dateFrom && date < filters.dateFrom) return false
        if (filters.dateTo && date > filters.dateTo) return false
        return true
      })
      .map(([marketTicker]) => marketTicker))
    markets = intersect(markets, settlementDateMarkets)
  }
  const filteredByTradeFields = Boolean(filters.direction || filters.role || filters.priceMin || filters.priceMax)
  const matchingTradeIds = new Set<string>()
  if (filteredByTradeFields) {
    marketConstraint = true
    const tradeMarkets = new Set(initiallyMatched
      .filter((activity): activity is TradeActivity => activity.kind === 'Trade' && matchesTradeFilters(activity, filters))
      .map(trade => {
        matchingTradeIds.add(trade.id)
        return trade.marketTicker
      }))
    markets = intersect(markets, tradeMarkets)
  }
  if (filters.result) {
    marketConstraint = true
    const resultMarkets = new Set(Array.from(settlements.entries())
      .filter(([, settlement]) => settlement.result === filters.result)
      .map(([marketTicker]) => marketTicker))
    markets = intersect(markets, resultMarkets)
  }
  if (!marketConstraint) return initiallyMatched
  return initiallyMatched.filter(activity => {
    if (!activity.marketTicker || !markets.has(activity.marketTicker)) return false
    if (filteredByTradeFields && activity.kind === 'Trade') return matchingTradeIds.has(activity.id)
    return true
  })
}

const realizationDateMatches = (date: string, filters: AnalysisFilterState) => {
  const day = localDate(date)
  return (!filters.dateFrom || day >= filters.dateFrom) && (!filters.dateTo || day <= filters.dateTo)
}

export const filterActivities = (
  activities: Activity[],
  filters: AnalysisFilterState = EMPTY_FILTERS,
  friendlyNames: Record<string, string> = {},
  fallbacks: Record<string, SettlementFallback> = {}
) => {
  if (!activities.some(activity => activity.source === 'polymarket')) return filterKalshiActivities(activities, filters, friendlyNames, fallbacks)
  const kalshiIds = new Set(filterKalshiActivities(activities.filter(activity => activity.source !== 'polymarket'), filters, friendlyNames, fallbacks).map(activity => activity.id))
  const evaluated = evaluatePolymarketTrades(activities)
  const matched = new Set<string>()
  const matchedMarkets = new Set<string>()
  for (const trade of evaluated.values()) {
    if (!matchesCommonFilters(trade, filters, friendlyNames) || !matchesTradeFilters(trade, filters)) continue
    if (filters.result && trade.result !== filters.result) continue
    if (filters.dateBasis === 'settlementDate' && (filters.dateFrom || filters.dateTo) && !trade.realizations?.some(item => realizationDateMatches(item.date, filters))) continue
    matched.add(trade.id)
    matchedMarkets.add(trade.marketTicker)
  }
  return activities.filter(activity => {
    if (activity.source !== 'polymarket') return kalshiIds.has(activity.id)
    if (activity.kind === 'Trade') return matched.has(activity.id)
    if (!matchesCommonFilters(activity, filters, friendlyNames)) return false
    const constrained = filters.direction || filters.role || filters.priceMin || filters.priceMax || filters.result
    if (constrained && !matchedMarkets.has(activity.marketTicker)) return false
    return filters.dateBasis !== 'settlementDate' || realizationDateMatches(activity.originalDate, filters)
  })
}

const hasRealization = (trade: EvaluatedTrade) => trade.netPnl !== null
const realizedCost = (trade: EvaluatedTrade) => trade.realizedCost ?? trade.cost
const realizedFees = (trade: EvaluatedTrade) => trade.realizedFees ?? trade.fee
const investedCapital = (trade: EvaluatedTrade) => trade.capitalInvested ?? trade.cost
const openCapital = (trade: EvaluatedTrade) => trade.openCost ?? (trade.settled ? 0 : trade.cost + trade.fee)

const filterRealizations = (trade: EvaluatedTrade, filters: AnalysisFilterState): EvaluatedTrade => {
  if (trade.source !== 'polymarket' || filters.dateBasis !== 'settlementDate' || !(filters.dateFrom || filters.dateTo)) return trade
  const realizations = trade.realizations?.filter(item => realizationDateMatches(item.date, filters)) ?? []
  return { ...trade, realizations, realizedCost: sum(realizations.map(item => item.cost)), realizedFees: sum(realizations.map(item => item.fees)), payout: sum(realizations.map(item => item.payout)), grossPnl: sum(realizations.map(item => item.grossPnl)), netPnl: realizations.length ? sum(realizations.map(item => item.netPnl)) : null }
}

const aggregateTrades = (key: string, label: string, trades: EvaluatedTrade[]): Breakdown => {
  const settled = trades.filter(hasRealization)
  const cost = sum(settled.map(realizedCost))
  const totalCost = sum(trades.map(investedCapital))
  const fees = sum(trades.map(trade => trade.fee))
  const totalRealizedFees = sum(settled.map(realizedFees))
  const pnl = sum(settled.map(trade => trade.netPnl))
  const markets = new Map<string, number>()
  settled.forEach(trade => markets.set(trade.marketTicker, (markets.get(trade.marketTicker) ?? 0) + (trade.netPnl ?? 0)))
  const winners = Array.from(markets.values()).filter(value => value > 0).length
  return {
    key,
    label,
    trades: trades.length,
    volume: sum(trades.map(trade => trade.amount)),
    cost,
    totalCost,
    fees,
    realizedFees: totalRealizedFees,
    settledTrades: settled.length,
    payout: sum(settled.map(trade => trade.payout)),
    pnl,
    roi: ratio(pnl, cost + totalRealizedFees),
    winRate: ratio(winners, markets.size)
  }
}

const group = <T>(items: T[], getKey: (item: T) => string) => {
  const groups = new Map<string, T[]>()
  items.forEach(item => {
    const key = getKey(item)
    const entries = groups.get(key)
    if (entries) entries.push(item)
    else groups.set(key, [item])
  })
  return groups
}

const buildMarkets = (trades: EvaluatedTrade[]): MarketAggregate[] => Array.from(group(trades, trade => trade.marketTicker))
  .map(([marketTicker, marketTrades]) => {
    const aggregate = aggregateTrades(marketTicker, marketTicker, marketTrades)
    const ordered = [...marketTrades].sort((a, b) => byDate(a.originalDate) - byDate(b.originalDate))
    const settled = marketTrades.some(hasRealization)
    const settlementDate = marketTrades.map(trade => trade.settlementDate).filter((date): date is string => Boolean(date)).sort().at(-1) ?? null
    return {
      ...aggregate,
      source: marketTrades[0].source,
      openCapital: sum(marketTrades.map(openCapital)),
      marketTicker,
      eventTicker: marketTrades[0].eventTicker,
      seriesTicker: marketTrades[0].seriesTicker,
      firstTrade: ordered[0].originalDate,
      lastTrade: ordered.at(-1)?.originalDate ?? ordered[0].originalDate,
      settlementDate,
      result: marketTrades.find(trade => trade.result)?.result ?? null,
      settled,
      holdMinutes: settlementDate ? Math.max(0, (byDate(settlementDate) - byDate(ordered[0].originalDate)) / 60000) : null
    }
  })
  .sort((a, b) => byDate(b.lastTrade) - byDate(a.lastTrade))

const buildEvents = (activities: Activity[], markets: MarketAggregate[]): EventAggregate[] => Array.from(group(markets, market => market.eventTicker))
  .map(([eventTicker, eventMarkets]) => {
    const eventActivities = activities
      .filter(activity => activity.eventTicker === eventTicker)
      .sort((a, b) => byDate(a.originalDate) - byDate(b.originalDate))
    const volume = sum(eventMarkets.map(market => market.volume))
    const cost = sum(eventMarkets.map(market => market.cost))
    const totalCost = sum(eventMarkets.map(market => market.totalCost))
    const fees = sum(eventMarkets.map(market => market.fees))
    const realizedFees = sum(eventMarkets.map(market => market.realizedFees))
    const pnl = sum(eventMarkets.map(market => market.pnl))
    const settled = eventMarkets.filter(market => market.settled)
    return {
      key: eventTicker,
      label: eventTicker,
      eventTicker,
      seriesTicker: eventMarkets[0].seriesTicker,
      marketCount: eventMarkets.length,
      firstTrade: eventMarkets.reduce((earliest, market) => byDate(market.firstTrade) < byDate(earliest) ? market.firstTrade : earliest, eventMarkets[0].firstTrade),
      lastTrade: eventMarkets.reduce((latest, market) => byDate(market.lastTrade) > byDate(latest) ? market.lastTrade : latest, eventMarkets[0].lastTrade),
      markets: eventMarkets,
      activities: eventActivities,
      trades: eventMarkets.reduce((total, market) => total + market.trades, 0),
      volume,
      cost,
      totalCost,
      fees,
      realizedFees,
      settledTrades: eventMarkets.reduce((total, market) => total + market.settledTrades, 0),
      payout: sum(eventMarkets.map(market => market.payout)),
      pnl,
      roi: ratio(pnl, cost + realizedFees),
      winRate: ratio(settled.filter(market => market.pnl > 0).length, settled.length)
    }
  })
  .sort((a, b) => byDate(b.lastTrade) - byDate(a.lastTrade))

const addCumulative = (days: Omit<DailyAggregate, 'cumulativePnl'>[]): DailyAggregate[] => {
  let cumulative = n(0)
  return days.sort((a, b) => a.date.localeCompare(b.date)).map(day => {
    cumulative = cumulative.plus(day.pnl)
    return { ...day, cumulativePnl: number(cumulative) }
  })
}

const dailyFromTrades = (trades: EvaluatedTrade[]) => addCumulative(Array.from(group(trades, trade => localDate(trade.originalDate)))
  .map(([date, dayTrades]) => ({
    date,
    pnl: sum(dayTrades.map(trade => trade.netPnl)),
    grossPnl: sum(dayTrades.map(trade => trade.grossPnl)),
    fees: sum(dayTrades.map(trade => trade.fee)),
    trades: dayTrades.length,
    settledTrades: dayTrades.filter(hasRealization).length,
    pendingTrades: dayTrades.filter(trade => trade.source === 'polymarket' ? (trade.openAmount ?? 0) > 0 || Boolean(trade.accountingWarning) : !trade.settled).length,
    markets: new Set(dayTrades.map(trade => trade.marketTicker)).size
  })))

const dailyFromSettlements = (markets: MarketAggregate[]) => addCumulative(Array.from(group(
  markets.filter(market => market.settled && market.settlementDate),
  market => localDate(market.settlementDate ?? market.lastTrade)
)).map(([date, dayMarkets]) => ({
  date,
  pnl: sum(dayMarkets.map(market => market.pnl)),
  grossPnl: sum(dayMarkets.map(market => market.pnl + market.realizedFees)),
  fees: sum(dayMarkets.map(market => market.realizedFees)),
  trades: dayMarkets.reduce((total, market) => total + market.trades, 0),
  settledTrades: dayMarkets.reduce((total, market) => total + market.settledTrades, 0),
  markets: dayMarkets.length
})))

const dailyRealizations = (trades: EvaluatedTrade[], markets: MarketAggregate[]) => {
  const kalshi = dailyFromSettlements(markets.filter(market => market.source !== 'polymarket'))
  const entries = trades.filter(trade => trade.source === 'polymarket').flatMap(trade => (trade.realizations ?? []).map(realization => ({ trade, realization })))
  const poly = Array.from(group(entries, entry => localDate(entry.realization.date))).map(([date, entries]) => ({
    date, pnl: sum(entries.map(entry => entry.realization.netPnl)), grossPnl: sum(entries.map(entry => entry.realization.grossPnl)), fees: sum(entries.map(entry => entry.realization.fees)),
    trades: new Set(entries.map(entry => entry.trade.id)).size, settledTrades: new Set(entries.map(entry => entry.trade.id)).size, pendingTrades: 0, markets: new Set(entries.map(entry => entry.trade.marketTicker)).size
  }))
  return addCumulative(Array.from(group([...kalshi, ...poly], day => day.date)).map(([date, days]) => ({ date, pnl: sum(days.map(day => day.pnl)), grossPnl: sum(days.map(day => day.grossPnl)), fees: sum(days.map(day => day.fees)), trades: sum(days.map(day => day.trades)), settledTrades: sum(days.map(day => day.settledTrades)), pendingTrades: 0, markets: sum(days.map(day => day.markets)) })))
}

const PRICE_RANGES = [
  { label: '1¢', min: 1, max: 1 },
  { label: '2–5¢', min: 2, max: 5 },
  { label: '6–20¢', min: 6, max: 20 },
  { label: '21–39¢', min: 21, max: 39 },
  { label: '40–60¢', min: 40, max: 60 },
  { label: '61–79¢', min: 61, max: 79 },
  { label: '80–94¢', min: 80, max: 94 },
  { label: '95–98¢', min: 95, max: 98 },
  { label: '99¢', min: 99, max: 99 }
]

const buildPriceBuckets = (trades: EvaluatedTrade[]): PriceBucket[] => PRICE_RANGES.map(range => ({
  ...aggregateTrades(range.label, range.label, trades.filter(trade => trade.effectivePrice >= (range.min === 1 ? 0 : range.min) && (range.max === 99 ? trade.effectivePrice <= 100 : trade.effectivePrice < range.max + 1))),
  min: range.min,
  max: range.max
}))

const buildCompactPositions = (trades: EvaluatedTrade[]): CompactPosition[] => Array.from(group(trades, trade => `${trade.marketTicker}:${trade.tokenId ?? trade.direction}`))
  .map(([key, positionTrades]) => {
    const aggregate = aggregateTrades(key, key, positionTrades)
    const ordered = [...positionTrades].sort((a, b) => byDate(a.originalDate) - byDate(b.originalDate))
    return {
      ...aggregate,
      source: positionTrades[0].source,
      outcome: positionTrades[0].outcome,
      marketSlug: positionTrades[0].marketSlug,
      marketTicker: positionTrades[0].marketTicker,
      eventTicker: positionTrades[0].eventTicker,
      direction: positionTrades[0].direction,
      averagePrice: ratio(sum(positionTrades.map(trade => trade.amount * trade.effectivePrice)), aggregate.volume) ?? 0,
      firstTrade: ordered[0].originalDate,
      lastTrade: ordered.at(-1)?.originalDate ?? ordered[0].originalDate,
      result: positionTrades.find(trade => trade.result)?.result ?? null
    }
  })
  .sort((a, b) => byDate(b.lastTrade) - byDate(a.lastTrade))

const seriesBreakdown = (trades: EvaluatedTrade[]) => Array.from(group(trades, trade => trade.seriesTicker))
  .map(([key, seriesTrades]) => aggregateTrades(key, key, seriesTrades))
  .sort((a, b) => b.pnl - a.pnl)

const median = (values: number[]) => {
  if (!values.length) return null
  const ordered = [...values].sort((a, b) => a - b)
  const middle = Math.floor(ordered.length / 2)
  return ordered.length % 2 ? ordered[middle] : (ordered[middle - 1] + ordered[middle]) / 2
}

export const analyzeActivities = (
  allActivities: Activity[],
  filters: AnalysisFilterState = EMPTY_FILTERS,
  friendlyNames: Record<string, string> = {},
  fallbacks: Record<string, SettlementFallback> = {}
): AnalysisResult => {
  const activities = filterActivities(allActivities, filters, friendlyNames, fallbacks)
  const trades = evaluateTrades(activities, allActivities, fallbacks).map(trade => filterRealizations(trade, filters))
  const markets = buildMarkets(trades)
  const hasDateFilter = Boolean(filters.dateFrom || filters.dateTo)
  const calendarActivities = hasDateFilter
    ? filterActivities(allActivities, { ...filters, dateFrom: '', dateTo: '' }, friendlyNames, fallbacks)
    : activities
  const calendarTrades = hasDateFilter ? evaluateTrades(calendarActivities, allActivities, fallbacks) : trades
  const calendarMarkets = hasDateFilter ? buildMarkets(calendarTrades) : markets
  const events = buildEvents(activities, markets)
  const settledTrades = trades.filter(hasRealization)
  const settledMarkets = markets.filter(market => market.settled)
  const openTrades = trades.filter(trade => openCapital(trade) > 0)
  const cost = sum(settledTrades.map(realizedCost))
  const fees = sum(trades.map(trade => trade.fee))
  const totalRealizedFees = sum(settledTrades.map(realizedFees))
  const allCost = sum(trades.map(investedCapital))
  const grossPnl = sum(settledTrades.map(trade => trade.grossPnl))
  const netPnl = sum(settledTrades.map(trade => trade.netPnl))
  const positiveMarketPnl = sum(settledMarkets.filter(market => market.pnl > 0).map(market => market.pnl))
  const negativeMarketPnl = sum(settledMarkets.filter(market => market.pnl < 0).map(market => market.pnl))
  const non99 = settledTrades.filter(trade => trade.effectivePrice !== 99)
  const non99Cost = sum(non99.map(trade => realizedCost(trade) + realizedFees(trade)))
  const non99Pnl = sum(non99.map(trade => trade.netPnl))
  const absoluteMarketPnl = sum(settledMarkets.map(market => Math.abs(market.pnl)))
  const topFive = [...settledMarkets].sort((a, b) => Math.abs(b.pnl) - Math.abs(a.pnl)).slice(0, 5)
  const topFivePnl = sum(topFive.map(market => Math.abs(market.pnl)))
  const holdWeight = sum(settledMarkets.filter(market => market.holdMinutes !== null).map(market => market.volume))
  const weightedHold = sum(settledMarkets.map(market => (market.holdMinutes ?? 0) * market.volume))
  const deposits = sum(activities.filter((activity): activity is CashActivity => activity.kind === 'Deposit').map(activity => activity.amount))
  const withdrawals = sum(activities.filter((activity): activity is CashActivity => activity.kind === 'Withdrawal').map(activity => activity.amount))
  const credits = sum(activities.filter((activity): activity is CashActivity => activity.kind === 'Credit').map(activity => activity.amount))

  return {
    warnings: Array.from(new Set(trades.map(trade => trade.accountingWarning).filter((warning): warning is string => Boolean(warning)))),
    summary: {
      trades: trades.length,
      orders: activities.filter(activity => activity.kind === 'Order').length,
      settlements: settledMarkets.length,
      markets: markets.length,
      events: events.length,
      volume: sum(trades.map(trade => trade.amount)),
      cost,
      totalCost: allCost,
      fees,
      realizedFees: totalRealizedFees,
      payout: sum(settledTrades.map(trade => trade.payout)),
      grossPnl,
      netPnl,
      roi: ratio(netPnl, cost + totalRealizedFees),
      pnlToVolume: settledMarkets.length ? ratio(netPnl, sum(trades.map(trade => trade.amount))) : null,
      marketWinRate: ratio(settledMarkets.filter(market => market.pnl > 0).length, settledMarkets.length),
      profitFactor: negativeMarketPnl ? positiveMarketPnl / Math.abs(negativeMarketPnl) : null,
      weightedEntryPrice: ratio(sum(trades.map(trade => trade.amount * trade.effectivePrice)), sum(trades.map(trade => trade.amount))),
      feeRate: ratio(fees, allCost),
      averageFill: ratio(sum(trades.map(trade => trade.amount)), trades.length),
      medianFill: median(trades.map(trade => trade.amount)),
      holdMinutes: ratio(weightedHold, holdWeight),
      non99Roi: ratio(non99Pnl, non99Cost),
      topFiveConcentration: ratio(topFivePnl, absoluteMarketPnl),
      openCapital: sum(openTrades.map(openCapital)),
      openMarkets: new Set(openTrades.map(trade => trade.marketTicker)).size,
      positiveFills: settledTrades.filter(trade => (trade.netPnl ?? 0) > 0).length,
      negativeFills: settledTrades.filter(trade => (trade.netPnl ?? 0) < 0).length,
      deposits,
      withdrawals,
      credits,
      netCashFlow: deposits + credits - withdrawals
    },
    activities,
    trades,
    markets,
    events,
    dailyTrade: dailyFromTrades(trades),
    dailySettlement: dailyRealizations(trades, markets),
    calendarTrade: dailyFromTrades(calendarTrades),
    calendarSettlement: dailyRealizations(calendarTrades, calendarMarkets),
    priceBuckets: buildPriceBuckets(trades),
    byDirection: ['Yes', 'No'].map(direction => aggregateTrades(direction, direction, trades.filter(trade => trade.direction === direction))),
    byRole: ['Maker', 'Taker', ...(trades.some(trade => trade.orderType === 'Unknown') ? ['Unknown'] : [])].map(role => aggregateTrades(role, role, trades.filter(trade => trade.orderType === role))),
    compactPositions: buildCompactPositions(trades),
    series: seriesBreakdown(trades)
  }
}
